require_once __DIR__.'/includes/bootstrap.php';require_role(['admin','receptionniste','accueil','caissier','production']);$page_title='Commandes & dépôts';$rows=db()->query("SELECT o.*,o.reference AS code,o.date_promise AS date_prevue,o.depose_par AS user_id,c.nom,c.prenom,c.telephone FROM commandes o JOIN clients c ON c.id=o.client_id ORDER BY o.id DESC LIMIT 500")->fetchAll();require 'includes/header.php';?>
<div class="panel"><div class="panel-head"><h2>Suivi des dépôts</h2><div class="actions"><input class="search" data-filter="#orders" placeholder="Rechercher..."><?php if(can_manage()):?><a class="btn" href="order_new.php">＋ Nouveau dépôt</a><?php endif;?></div></div><div class="table-wrap"><table id="orders"><thead><tr><th>Référence</th><th>Client</th><th>Téléphone</th><th>Type</th><th>Date dépôt</th><th>Retrait prévu</th><th>Total</th><th>État</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['code'])?></b></td><td><?=e($r['prenom'].' '.$r['nom'])?></td><td><?=e($r['telephone'])?></td><td><span class="badge"><?=e(ucfirst($r['type_depot']))?></span></td><td><?=date('d/m/Y',strtotime($r['date_depot']))?></td><td><?=e($r['date_prevue'])?></td><td><?=money($r['total'])?></td><td><span class="badge <?=e($r['statut'])?>"><?=e(status_label($r['statut']))?></span></td><td><a class="btn light small" href="order_view.php?id=<?=$r['id']?>">Détails</a></td></tr><?php endforeach;?></tbody></table></div></div>
